import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:go_router/go_router.dart';
import 'package:collega_app/core/ui/theme/cg_theme.dart';

void main() {
  testWidgets('tab switch via go inside ShellRoute animates?', (tester) async {
    final router = GoRouter(initialLocation: '/home', routes: [
      ShellRoute(builder: (c, s, child) => child, routes: [
        GoRoute(path: '/home', builder: (_, __) => const Text('HOME', textDirection: TextDirection.ltr)),
        GoRoute(path: '/colleges', builder: (_, __) => const Text('COLL', textDirection: TextDirection.ltr)),
      ]),
    ]);
    await tester.pumpWidget(MaterialApp.router(theme: buildCgMaterialTheme(CgThemeData.light), routerConfig: router));
    await tester.pumpAndSettle();
    router.go('/colleges');
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 100));
    final dx = tester.getTopLeft(find.text('COLL')).dx;
    // ignore: avoid_print
    print('COLL dx at 100ms = $dx ; HOME present=${find.text('HOME').evaluate().isNotEmpty}; CupertinoPageTransition=${find.byType(CupertinoPageTransition).evaluate().length}');
    await tester.pumpAndSettle();
  });
}
